test("HTTP signature failures return 401 without state changes, including replay-token requests", async t => {
  const { dir, post, signed } = await fixture(t);
  await signed(JSON.stringify(event("evt_existing")));
  const before = snapshot(dir);
  const raw = JSON.stringify(event("evt_unsigned"));
  const now = Math.floor(Date.now() / 1000);
  for (const headers of [
    {},
    { "Paygate-Signature": signature(raw, now, "wrong-secret") },
    { "Paygate-Signature": signature(raw, now - 301) },
    { "Paygate-Signature": signature(raw, now + 3600) },
    { "X-Paygate-Replay-Token": "untrusted-vendor-replay-token" },
    { "Paygate-Signature": "malformed", "X-Paygate-Replay-Token": "untrusted-vendor-replay-token" },
  ]) {
    assert.equal((await post(raw, headers)).status, 401);
    assert.deepEqual(snapshot(dir), before);
  }
  assert.equal((await post("not json")).status, 401);
  assert.deepEqual(snapshot(dir), before);
});

test("HTTP duplicates preserve refunds, audit, and original payload, even concurrently", async t => {
  const { store, dir, signed, post } = await fixture(t);
  const ev = event("evt_http");
  const raw = JSON.stringify(ev, null, 2) + "\n";
  assert.deepEqual(await signed(raw), { status: 200, body: { received: true, duplicate: false } });
  const before = snapshot(dir);
  const changed = JSON.stringify({ ...ev, data: { ...ev.data, amount: 900000, reason: "changed retry" } });
  const replies = await Promise.all(Array.from({ length: 5 }, () => signed(changed)));
  for (const reply of replies) {
    assert.deepEqual(reply, { status: 200, body: { received: true, duplicate: true } });
  }
  assert.deepEqual(snapshot(dir), before);
  assert.equal(store.loadRawEvent(ev.event_id), raw);
  assert.equal(store.listRefunds().length, 1);
  assert.equal((await post(raw)).status, 401); // duplicates still require authentication
  assert.deepEqual(snapshot(dir), before);
});

test("signed invalid events return 400, and unknown event types are acknowledged and deduplicated", async t => {
  const { dir, signed, store } = await fixture(t);
  const before = snapshot(dir);
  for (const raw of ["not json", "null", "{}", JSON.stringify({ ...event("evt_bad"), created: "yesterday" }),
    JSON.stringify(event("evt_bad", "refund.requested", { amount: -1 })),
    JSON.stringify(event("evt_bad", "refund.requested", { amount: 1.5 })),
    JSON.stringify(event("evt_bad", "refund.requested", { currency: null })),
    JSON.stringify(event("evt_bad", "refund.cancelled", { refund_id: "" }))]) {
    assert.throws(() => parseEvent(raw), EventError);
    assert.equal((await signed(raw)).status, 400);
    assert.deepEqual(snapshot(dir), before);
  }
  const ignored = JSON.stringify({ event_id: "evt_unknown", type: "payment.updated", created: NOW, data: {} });
  assert.deepEqual(await signed(ignored), { status: 200, body: { received: true, duplicate: false } });
  assert.equal(store.listRefunds().length, 0);
  const processed = snapshot(dir);
  assert.deepEqual(await signed(ignored), { status: 200, body: { received: true, duplicate: true } });
  assert.deepEqual(snapshot(dir), processed);
});

test("internal replay retains bearer authorization and cannot re-drive processed events", async t => {
  const { store, url } = await fixture(t);
  store.saveRawEvent("evt_failed", JSON.stringify(event("evt_failed")));
  const replay = (headers = {}) => fetch(`${url}/admin/replay/evt_failed`, { method: "POST", headers });
  assert.equal((await replay({ "X-Paygate-Replay-Token": "untrusted-vendor-replay-token" })).status, 401);
  assert.equal((await replay({ Authorization: "Bearer viewer-test-key" })).status, 403);
  assert.equal(store.listRefunds().length, 0);
  const success = await replay({ Authorization: "Bearer ops-test-key" });
  assert.equal(success.status, 200);
  assert.deepEqual(await success.json(), { replayed: true, outcome: "processed" });
  assert.equal((await replay({ Authorization: "Bearer ops-test-key" })).status, 409);
  assert.equal(store.listRefunds().length, 1);
});
